window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"3tzQnA7WKmU","speaker":"Odo Tevi","role":"Permanent Representative","country":"Vanuatu","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=3tzQnA7WKmU","date":"20260928","title":"🇻🇺 Vanuatu - Permanent Representative Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1758,"words":4009,"counts":{"claims":49,"promises":4,"attacks":1},"topics":[{"topic":"UN reform","share":0.2185,"seconds":384},{"topic":"BBJ agreement","share":0.0747,"seconds":131},{"topic":"International law","share":0.0722,"seconds":127},{"topic":"multilateralism","share":0.0695,"seconds":122},{"topic":"New Caledonia","share":0.0434,"seconds":76},{"topic":"Vanuatu identity","share":0.0384,"seconds":68},{"topic":"West Papua","share":0.0384,"seconds":67},{"topic":"Vanuatu independence","share":0.038,"seconds":67},{"topic":"Vanuatu-France dispute","share":0.0377,"seconds":66},{"topic":"AI transformation","share":0.0377,"seconds":66},{"topic":"Sea level rise","share":0.037,"seconds":65},{"topic":"France ICJ","share":0.0362,"seconds":64},{"topic":"Vanuatu economy","share":0.0359,"seconds":63},{"topic":"Vanuatu climate","share":0.0359,"seconds":63},{"topic":"Climate finance","share":0.0356,"seconds":63},{"topic":"Pacific climate","share":0.0355,"seconds":62},{"topic":"Pacific climate finance","share":0.0354,"seconds":62},{"topic":"Pacific security","share":0.0351,"seconds":62},{"topic":"AI governance","share":0.0351,"seconds":62},{"topic":"Ceremony","share":0.0097,"seconds":17}],"timeline":[[1,68,"Vanuatu identity"],[70,132,"UN reform"],[133,203,"UN reform"],[205,267,"International law"],[268,333,"International law"],[333,395,"Pacific security"],[396,461,"Sea level rise"],[462,525,"Vanuatu economy"],[526,593,"Vanuatu independence"],[594,656,"Climate finance"],[657,719,"Pacific climate finance"],[720,783,"Pacific climate"],[783,845,"BBJ agreement"],[846,916,"BBJ agreement"],[916,982,"AI transformation"],[983,1045,"AI governance"],[1046,1109,"Vanuatu climate"],[1110,1179,"UN reform"],[1180,1248,"West Papua"],[1249,1325,"New Caledonia"],[1325,1392,"Vanuatu-France dispute"],[1393,1456,"France ICJ"],[1457,1517,"UN reform"],[1518,1580,"UN reform"],[1581,1642,"multilateralism"],[1642,1704,"multilateralism"],[1705,1765,"UN reform"],[1766,1783,"Ceremony"]],"stances":{"Vanuatu identity":"Odo Tevi introduces himself as the representative of Vanuatu and describes his nation's composition and values.","UN reform":"Odo Tevi expresses appreciation for the outgoing Secretary General's service and hopes the successor maintains a commitment to all member states.","International law":"Odo Tevi states that international law and multilateral institutions are essential for the security of small states whose capabilities are limited compared to major powers.","Pacific security":"Odo Tevi argues that Pacific security encompasses broad issues like climate change and economic stability rather than just military competition, and opposes the region becoming an arena for great power rivalry.","Sea level rise":"Odo Tevi affirms the continuity of statehood and preservation of maritime rights for Vanuatu in the face of sea level rise while calling for a broader understanding of international peace and security that reflects the realities of small island developing states.","Vanuatu economy":"Odo Tevi argues that global economic factors directly impact Vanuatu's domestic development and that international diplomacy is fundamentally about improving the lives of its citizens.","Vanuatu independence":"Odo Tevi states that Vanuatu's 46th independence anniversary serves as a reminder of the nation's resilience and a call to build a stronger future despite past challenges.","Climate finance":"Odo Tevi states that Vanuatu requires international solidarity and partnership rather than charity to address climate change, disaster resilience, and economic shocks.","Pacific climate finance":"Odo Tevi calls for easier access to finance and stronger international cooperation to support Pacific resilience against climate change and El Niño.","Pacific climate":"Odo Tevi calls for international support to help Pacific nations prepare for and recover from climate disasters rather than preventing natural phenomena.","BBJ agreement":"Odo Tevi supports the BBJ agreement as a step for marine biodiversity protection and calls for its rapid implementation and ratification.","AI transformation":"Odo Tevi argues that technological transformation must not create a new hierarchy between those who possess technology and those who experience its consequences.","AI governance":"Odo Tevi argues that small states must be active participants in shaping AI governance to prevent deepening inequalities and dependency.","Vanuatu climate":"Odo Tevi asserts that Vanuatu remains committed to advocating for climate justice and ensuring vulnerable nations lead in international decision-making despite global dependencies.","West Papua":"Odo Tevi expresses deep concern regarding human rights violations in West Papua and calls for a UN commissioner visit.","New Caledonia":"Odo Tevi expresses concern over economic disparities affecting the Kanak people and calls for their full implementation of UN resolutions to ensure equitable development.","Vanuatu-France dispute":"Odo Tevi asserts that the Matthew and Hunter Islands are an integral part of Vanuatu's territory and confirms that the FATU government has initiated legal proceedings against France regarding sovereignty over these islands.","France ICJ":"Odo Tevi expresses appreciation for France's partnership on climate action and invites France to consent to the International Court of Justice's jurisdiction.","multilateralism":"Odo Tevi states that Vanuatu will continue to defend the multilateral system, international law, and the principle that every nation matters regardless of size.","Ceremony":"Odo Tevi thanks the chair of delegation and yields the floor to another representative."},"claims":[{"t":52,"quote":"a nation of more than 80 islands, of many indigenous communities and languages","topic":"Vanuatu identity","kind":"fact"},{"t":72,"quote":"this session also carries a particular s significance for us because it is the final high level general assembly of your tenure as secretary general of the United Nations.","topic":"UN reform","kind":"fact"},{"t":106,"quote":"Over the course of your tenure, you have led United Nations through some of the most tumultuous periods in recent international history.","topic":"UN reform","kind":"fact"},{"t":140,"quote":"The world needs the United Nations more than ever and the United Nations must deliver for the people who depend on it.","topic":"UN reform","kind":"fact"},{"t":189,"quote":"We are witnessing geopolitical competition, strategic rivalry, armed conflicts, growing military expenditures, economic fragmentation, technological disruption, and a weakening of confidence in the multilateral institutions.","topic":"UN reform","kind":"fact"},{"t":205,"quote":"The rules that were designed to provide predictability and stability are increasingly being tested.","topic":"International law","kind":"fact"},{"t":230,"quote":"Small states do not possess the military, economic or technological capabilities of major powers.","topic":"International law","kind":"fact"},{"t":268,"quote":"It establishes several It establishes sovereign equality, peaceful settlement of disputes and the prohibition or of the threat or or use of force as fundamental principles of international relations.","topic":"International law","kind":"fact"},{"t":380,"quote":"For Vanoatu, a cyclone that destroys a school is a security issue.","topic":"Pacific security","kind":"fact"},{"t":385,"quote":"A rise in food and energy prices as recently experienced by Middle East conflict is a security issue.","topic":"Pacific security","kind":"fact"},{"t":396,"quote":"A cyber attack against critical infrastructure is a security issue.","topic":"Sea level rise","kind":"fact"},{"t":401,"quote":"Sea level rise also resess fundamental questions on so on on sovereignity, identity and security.","topic":"Sea level rise","kind":"fact"},{"t":425,"quote":"These are realities faced by small island development states.","topic":"Sea level rise","kind":"fact"},{"t":462,"quote":"A disruption in international shipping can increase the price of food in our islands.","topic":"Vanuatu economy","kind":"fact"},{"t":467,"quote":"A change in global global interest rates can increase the cost of borrowing.","topic":"Vanuatu economy","kind":"fact"},{"t":472,"quote":"A crisis in implement in in international development finance can delay a school, a hospital, a road or a climate resilience project.","topic":"Vanuatu economy","kind":"fact"},{"t":482,"quote":"And global economic uncertainty can affect tourism, investment, employment and government revenue for Vanuatu.","topic":"Vanuatu economy","kind":"fact"},{"t":527,"quote":"this year as Vanu celebrated its 46th independence anniversary, we reflected on how far our country has come since 1980.","topic":"Vanuatu independence","kind":"fact"},{"t":537,"quote":"Our independence was not given to us in a golden plate. It was achieved through the determination, courage, and sacrifice of our people supported by our brothers and sisters in the Pacific.","topic":"Vanuatu independence","kind":"fact"},{"t":549,"quote":"At our independence celebrations, we were reminded once again of the importance of solidarity, including the historic support of Papa New Guinea during our struggle for independence.","topic":"Vanuatu independence","kind":"fact"},{"t":609,"quote":"A small island country cannot finance all of its resilient needs alone.","topic":"Climate finance","kind":"fact"},{"t":613,"quote":"We cannot rebuild every road, bridge, school, and hospital after every disaster from domestic resources alone.","topic":"Climate finance","kind":"fact"},{"t":676,"quote":"keeping 1.5° C is vital for Pacific","topic":"Pacific climate finance","kind":"fact"},{"t":695,"quote":"developing strong El Nino event in the Pacific which threatens to bring more extreme heat rainfall, drought and flooding across the region","topic":"Pacific climate finance","kind":"fact"},{"t":724,"quote":"We call for stronger regional early warning system, prepositioned humanitarian assistance, rapid access to climate and disaster financing, and greater investment in resilient infrastructure and food and water security.","topic":"Pacific climate","kind":"fact"},{"t":739,"quote":"The Pacific does not ask ask the world to prevent El Nino. We ask the world to help us to prepare for it, withstand its impacts and recover with dignity.","topic":"Pacific climate","kind":"fact"},{"t":768,"quote":"Venote welcomes the entry into the force of the BBJ agreement.","topic":"Pacific climate","kind":"fact"},{"t":810,"quote":"Since the agreement entered into force on 17th January 2026 following its ratification by more than 60 states including Vanoatu and our Pacific neighbors","topic":"BBJ agreement","kind":"fact"},{"t":865,"quote":"The hosting of the inaugural Melanesian Ocean Summit in Port Mos Papa Nigini this year arrives at the critical juncture where one where on one hand we are faced with daily mounting challenges of the detrimental effects of climate change, the alarming degradation of our marine biodiversity, pervasive marine pollution and the overexloitation of our vital marine resources.","topic":"BBJ agreement","kind":"fact"},{"t":939,"quote":"Artificial intelligence is changing economies and societies. Digital technologies are changing the way governments operate. Energy systems are changing. Global trade is changing. Democratic demographic patterns are changing. And climate change is transforming the physical environment in which many of our societies exist.","topic":"AI transformation","kind":"fact"},{"t":993,"quote":"Artificial intelligence provide one example. AI offers enormous opportunities for education, healthcare, public administration, agriculture, climate forecasting, and economic development.","topic":"AI governance","kind":"fact"},{"t":1006,"quote":"But without appropriate governance, it it could also deepen existing inequalities.","topic":"AI governance","kind":"fact"},{"t":1046,"quote":"We depend on international markets. We depend on development partners. We depend on international shipping. We depend on imported fuel, fueled and manufactured goods.","topic":"Vanuatu climate","kind":"fact"},{"t":1067,"quote":"history has shown that some of the most important developments in international law and global governance have emerged because small and vulnerable states refused to remain silent.","topic":"Vanuatu climate","kind":"fact"},{"t":1146,"quote":"The General Assembly is the most representative body of the United Nations bringing together all 193 members on the basis of sovereign equality for countries such as Venatu.","topic":"UN reform","kind":"fact"},{"t":1170,"quote":"Such measures are in violation with the principles enshrined in the charter of the United Nations and adversely affect sustainable development outcomes of countries such as Cuba.","topic":"UN reform","kind":"fact"},{"t":1191,"quote":"Fanatu remains deeply concerned about reports of serious human rights violations affecting indigenous Papuans in West Papua.","topic":"West Papua","kind":"fact"},{"t":1199,"quote":"United Nations special procedures have also raised concerns regarding indigenous rights, displacement, cultural rights, environmental impacts and the treatment of human rights defenders in Papua.","topic":"West Papua","kind":"fact"},{"t":1211,"quote":"The call from the Pacific Forum leaders for the UN human rights commissioner visit to West Papu remains unheeded and needs to be action.","topic":"West Papua","kind":"fact"},{"t":1250,"quote":"persistent social economic disparities affecting affecting the Canak people including inequalities in employment, education, income and access to economic opportunities","topic":"New Caledonia","kind":"fact"},{"t":1278,"quote":"Reports from the Evelyn case supported by independent assessment point to the enduring effects of economic marginalization and uneven development","topic":"New Caledonia","kind":"fact"},{"t":1346,"quote":"at the end of August the FATU government initiated proceedings against France before the International Court of Justice concern concerning sovereignity over um N and um Lea Islands or Matthew and Hunter as they call in English","topic":"Vanuatu-France dispute","kind":"fact"},{"t":1367,"quote":"These islands are integral part of anatu's territory grounded in customary governance long-standing historical connections, indigenous ownership","topic":"Vanuatu-France dispute","kind":"fact"},{"t":1393,"quote":"France has stood alongside Vonoatu in advancing global climate action, including through its support for initiative before the International Court of Justice.","topic":"France ICJ","kind":"fact"},{"t":1473,"quote":"The UN80 reforms currently implemented are paramount to rebuild trust again at the United Nations and therefore needs to be managed diligently.","topic":"UN reform","kind":"fact"},{"t":1530,"quote":"Forato calls for UN Security Council that is more representative, transparent and accountable with and working methods that reflect today's realities and give all regions a meaningful voice.","topic":"UN reform","kind":"fact"},{"t":1581,"quote":"It tells us and it reminds us that the ultimate purpose of the international system is not power for its own sake. It is peace, justice, human dignity, development and cooperation.","topic":"multilateralism","kind":"fact"},{"t":1604,"quote":"Our independence is not merely the absence of colonial rule. Independence means the right of our people to determine our future.","topic":"multilateralism","kind":"fact"},{"t":1642,"quote":"There are communities facing humanitarian catastrophe. There's growing geopolitical revoly. There is economic uncertainty. There is climate disruption. There is technological transformation. And there is declining confidence in the international systems institutions.","topic":"multilateralism","kind":"fact"}],"promises":[{"t":1621,"quote":"That is why Venat will continue to defend the multilateral system.","topic":"multilateralism","kind":"promise"},{"t":1625,"quote":"That is why we will continue to defend international law","topic":"multilateralism","kind":"promise"},{"t":1629,"quote":"and that is why we will continue to speak for the principle that every nation regard regardless of size matters.","topic":"multilateralism","kind":"promise"},{"t":1763,"quote":"Vatu stands ready to do its path.","topic":"UN reform","kind":"promise"}],"attacks":[{"t":1162,"quote":"the imposition of cohesive economic measures, including unilateral sanctions against developing countries, is unfair and unjust.","topic":"UN reform","target":"Unilateral Sanctions"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":1,"topic":"Vanuatu identity","text":"the chair of delegation of Costa Rica. I now give the floor to his excellency Odo Tei, chair of delegation of Vanuatu. Mr. President of the General Assembly, Mr. Secretary General, Ladies and gentlemen, Mr. President, I have the honor to address this assembly on behalf of the government and the people of the Republic of Vanuatu. I bring with me the voice of a nation of more than 80 islands, of many indigenous communities and languages, and a nation whose identity has been shaped by the ocean, by custom, by faith, by resilience, and above all by commitment to peace."},{"t":70,"topic":"UN reform","text":"Mr. Secretary General, this session also carries a particular s significance for us because it is the final high level general assembly of your tenure as secretary general of the United Nations. On behalf of the government and people of Anatu, I wish to convey a profound appreciation for your service to the United Nations and your engagement with the people of the Pacific. Your visits to our region reflect an understanding that the concerns of small island development states deserve to be heard at a higher level. Over the course of your tenure, you have led United Nations through some of the most tumultuous periods in recent international history. You have stood consistently for at a time when multilateralism itself was under enomous pressure. Vanoatu hopes that the next Secretary General will carry forward that same commitment to all member states, large or small."},{"t":133,"topic":"UN reform","text":"Mr. President, Fenato comes to this 81st session of the General Assembly with a simple message. The world needs the United Nations more than ever and the United Nations must deliver for the people who depend on it. The theme of this session, restoring trust, managing transformation, a united nations that that delivers for all, therefore comes at an at an important moment. The 81st session open against a backdrop of profound geopolitical uncertainty and rapid transformation. For Vanoatu, developments in international system are never distant or abstract. The effects reach our villages, our markets, our schools, our hospitals, our oceans, and our homes. Mr. President, the international political and security environment is becoming increasingly difficult. We are witnessing geopolitical competition, strategic rivalry, armed conflicts, growing military expenditures, economic fragmentation, technological disruption, and a weakening of confidence in the multilateral institutions."},{"t":205,"topic":"International law","text":"The rules that were designed to provide predictability and stability are increasingly being tested. The prohibition against the use of force is being challenged. The international humanitarian law is being tested. The peaceful settlements of dispute is being undermined and the authority of international institution is being questioned for small states. This is deeply concerning. Small states do not possess the military, economic or technological capabilities of major powers. We do not have the ability to impose our will through co. Our security depends fundamentally on something else. International law, multilateral institutions, diplomacy, and the equal sovereignity of states. This is why Vanoatu has a profound interest in the success of the United Nations. The charter begins with a commitment to serve succeeding generations from the scourge of war and reaffirms the equal rights of nations large and small."},{"t":268,"topic":"International law","text":"It establishes several It establishes sovereign equality, peaceful settlement of disputes and the prohibition or of the threat or or use of force as fundamental principles of international relations. These are not merely legal concepts for Vanatu. They are our security architecture. When international law is respected, a small nation has protection. When the charter is respected, a small state has a voice. When disputes are resolved peacefully, a small state does not have to choose between submission and And when sovereignity is respected, independence has meaning. We therefore cannot accept a world in which international law applies differently according to the size, military strength or economic power of a state. that charter must apply equally to all. Mr. President, the security environment is also changing in ways that are particularly important for the Pacific region."},{"t":333,"topic":"Pacific security","text":"The Pacific islands are increasingly fueled through the lens of strategic competition. There is growing interest in our maritime spaces, our sea lions, our resources, and our geopolitical location. will welcome genuine partnerships. But we also say clearly the Pacific must not become an arena for great power competition at the expense of Pacific priorities. The security of the Pacific is not simply about military deployments or strategic competition. For us, security also means food security, energy security, water security, health security, economic security, cyber security, environmental security, and the security of our people from the impacts of climate change. For Vanoatu, a cyclone that destroys a school is a security issue. A rise in food and energy prices as recently experienced by Middle East conflict is a security issue. A disrupted shipping route is a security issue."},{"t":396,"topic":"Sea level rise","text":"A cyber attack against critical infrastructure is a security issue. Sea level rise also resess fundamental questions on so on on sovereignity, identity and security. Venote joins its Pacific colleagues in affirming the continuity of statehood and the preservation of maritime sun and sovereign rights in the face of sea level rise. The rights and dignity of affected persons must remain at the center of international response. These are realities faced by small island development states. We therefore call for a broader understanding of international peace and security. One that reflects the real realities of small island developing states. And we hope that these security concerns are well understood here at the United Nations. Mr. President, what happens here in New York does not remain here in New York. The decisions taken by major powers affect the smallest economies. A conflict thousands of kilometers away can increase the price of fuel in Vanuatu."},{"t":462,"topic":"Vanuatu economy","text":"A disruption in international shipping can increase the price of food in our islands. A change in global global interest rates can increase the cost of borrowing. A crisis in implement in in international development finance can delay a school, a hospital, a road or a climate resilience project. And global economic uncertainty can affect tourism, investment, employment and government revenue for Vanuatu. Therefore, foreign policy and domestic development are inseparable. Our international diplomacy is is ultimately about a people. It is about whether a child in Tana can attend school. Whether a farmer in Malikula can bring a produce to market. Whether a family in Toba has access to reliable electricity, whether a community in Panama can recover quickly after a natural disaster and whether our young people can find meaningful opportunities at home rather rather than being forced to live in search of them."},{"t":526,"topic":"Vanuatu independence","text":"Mr. President, this year as Vanu celebrated its 46th independence anniversary, we reflected on how far our country has come since 1980. Our independence was not given to us in a golden plate. It was achieved through the determination, courage, and sacrifice of our people supported by our brothers and sisters in the Pacific. At our independence celebrations, we were reminded once again of the importance of solidarity, including the historic support of Papa New Guinea during our struggle for independence. Our 46th independence anniversary was therefore not simply a celebration of the past. It was a call to build the future. The message of our national celebration was one of unity, national pride, resilience and determination to build a stronger, more prosperous Venatu for future generations. And this is important in the context of our discussions today. Vanatu has experienced cyclones, earthquakes, volcanic eruptions and economic shocks and other disasters."},{"t":594,"topic":"Climate finance","text":"Yet we continue to stand. We rebuild. We adapt and we move forward. Resilience is not simply something Vanu speaks about. It is something our people practice every day. But resilience also requires international solidarity. A small island country cannot finance all of its resilient needs alone. We cannot rebuild every road, bridge, school, and hospital after every disaster from domestic resources alone. We cannot absorb absorb indefinitely the economic consequences of external shocks. And we cannot protect our people from a changing climate without a meaningful international cooperation. Therefore, when we speak about climate finance, development finance, disaster resilience, and sustainable development, we are not asking merely for charity. We are asking for partnership, fairness, and the fulfillment of international commitments. That part partnership must include predictable and accessible finance for adaptation and for addressing loss and damage."},{"t":657,"topic":"Pacific climate finance","text":"Access to such finance must be made easier for the small island developing island state and must respond to the needs of our communities. We invite partners to support our Pacific resilience facility in bringing the necessary resources to support resilience efforts in the Pacific. At the same time, keeping 1.5° C is vital for Pacific. In light of the international court's advisory opinion, we ought we urge all members to give effect on their legal obligations through stronger climate actions and international cooperations. Mr. President, we are also deeply concerned by the developing strong El Nino event in the Pacific which threatens to bring more extreme heat rainfall, drought and flooding across the region. For Pacific Island countries, these are not simply materological events. They affect food and water security, agriculture, fisheries, health, livelihoods, and the resilience of already vulnerable communities."},{"t":720,"topic":"Pacific climate","text":"The international community must act before disaster strikes. We call for stronger regional early warning system, prepositioned humanitarian assistance, rapid access to climate and disaster financing, and greater investment in resilient infrastructure and food and water security. The Pacific does not ask ask the world to prevent El Nino. We ask the world to help us to prepare for it, withstand its impacts and recover with dignity. Mr. President, the ocean is central to Veno's identity, culture, food security, and prosperity. Protection of it is essential for the future of our people. Climate change, damage to the ocean, and loss of biodiversity are linked. We must address them together. Venote welcomes the entry into the force of the BBJ agreement. It is an important achievement for ocean governance and multilateral cooperation. For a nation whose identity, culture and prosperity are inseparable from the ocean."},{"t":783,"topic":"BBJ agreement","text":"The BBJ agreement represents an important step towards protecting marine biodiversity beyond national jurisdiction and ensuring that the benefits of a common ocean heritage are shared fairly and sustainably. Vanato stands ready to contribute to its effective implementation and to strengthening international cooperation for the protection of our oceans for generations to come. Since the agreement entered into force on 17th January 2026 following its ratification by more than 60 states including Vanoatu and our Pacific neighbors, the international community community has moved into a critical implementation phase. Watu looks forward to the first conference of the parties advancing the operationalization of marine protected areas, environmental impact assessments and the fair and equitable sharing of benefits from marine genetic resources. And we call on all states yet to ratify the agreement to do so without delay."},{"t":846,"topic":"BBJ agreement","text":"The implementation of the BB&amp;J agreement must respect sovereign rights and take full account of the sec special circumstances and capacity constraints of small island developing states. It must enable countries to participate effectively and and equally benefit from it. The hosting of the inaugural Melanesian Ocean Summit in Port Mos Papa Nigini this year arrives at the critical juncture where one where on one hand we are faced with daily mounting challenges of the detrimental effects of climate change, the alarming degradation of our marine biodiversity, pervasive marine pollution and the overexloitation of our vital marine resources. Yet some of these global issues have already escalated to a level where ensuring sustainability for future generations has become a critical concern highlighting the urgent need for improved management of our ocean resources. In today's world, science and technology and economic opportunities must also work closely with our traditional custodians in our vast coastal area to maintain respect for nature."},{"t":916,"topic":"AI transformation","text":"Our culture and tradition are deeply rooted in the ocean and hence our collective wisdom and collaboration to address the core issues affecting our people's livelihood livelihoods today and rescept the future of our ocean and communities is extremely paramount. Mr. President, the world is entering a period period of extraordinary transformation. Artificial intelligence is changing economies and societies. Digital technologies are changing the way governments operate. Energy systems are changing. Global trade is changing. Democratic demographic patterns are changing. And climate change is transforming the physical environment in which many of our societies exist. The question before us is ask is not whether trans transformation will occur. It will. The question is who will shape the transformation and who will benefit from it. For Vanoatu, the answer must be clear. Transformation must not create a new hierarchy between those who pro possess technology, capital and influence and those who merely experience the consequences."},{"t":983,"topic":"AI governance","text":"We need an international system in which developing countries and small states are participants in transformation not simply consumers of decisions made elsewhere. Artificial intelligence provide one example. AI offers enormous opportunities for education, healthcare, public administration, agriculture, climate forecasting, and economic development. But without appropriate governance, it it could also deepen existing inequalities. Small states need access to technology. We need digital infrastructure. We need skills and capacity. We need access to data and computing. And we need a meaning meaningful for voice in establishing the international norms that govern that govern emerging technologies. The digital future must not become another form of dependency. Mr. President, there is a tendency to describe small states primary in terms of our vulnerabilities. We are small. We are geographically dispersed. We are economically vulnerable. We have limited institutional capacity."},{"t":1046,"topic":"Vanuatu climate","text":"We depend on international markets. We depend on development partners. We depend on international shipping. We depend on imported fuel, fueled and manufactured goods. And yes, in many respects, we are dependent on the international system. But dependence must not be confused with powerlessness. Small states can lead. Indeed, history has shown that some of the most important developments in international law and global governance have emerged because small and vulnerable states refused to remain silent. Fenato is proud of its commitment to the global climate debate. We are proud of our advocacy for climate justice. We are proud of our role in advancing the recognition of the legal dimensions of climate change and we remain commitment committed to ensuring that the forces of those most vulnerable to climate change ahead in international decision making. In this vein, the FAT government wholeheartedly thank all the UN members who have supported us in this journey especially here at the UN General Assembly and International Court of Justice."},{"t":1110,"topic":"UN reform","text":"Our experience demonstrate an important principle. Influence is not determined solely by population, territory or military power. Influence can come from ideas. It can come from moral authority. It can come from coalition building. It can come from persistence. It can come from international law. And it come from the ability to bring different regions and groups together around a common cause. This is the strength of the general assembly. Every member states has a voice. Every member state has a vote and every member states large or small has a responsibility to contribute. The General Assembly is the most representative body of the United Nations bringing together all 193 members on the basis of sovereign equality for countries such as Venatu. This principle is fundamental. Mr. President, the imposition of cohesive economic measures, including unilateral sanctions against developing countries, is unfair and unjust. Such measures are in violation with the principles enshrined in the charter of the United Nations and adversely affect sustainable development outcomes of countries such as Cuba."},{"t":1180,"topic":"West Papua","text":"In this respect, we consistently call for the uplift of the economic embark on the Republic of Cuba. Mr. President, peace and security cannot be separated from human rights. Fanatu remains deeply concerned about reports of serious human rights violations affecting indigenous Papuans in West Papua. United Nations special procedures have also raised concerns regarding indigenous rights, displacement, cultural rights, environmental impacts and the treatment of human rights defenders in Papua. The call from the Pacific Forum leaders for the UN human rights commissioner visit to West Papu remains unheeded and needs to be action. Mr. President, Vanatu reaffirms its unwavering support for the decolonization of Kaki New Calonia which remains a nonselfgoverning territory under the purview of the United Nations. We reiterate the inelible right of the indigenous Kanak people to self-determination and call for a peaceful, inclusive, transparent and credible process consistent with the charter of the United Nations and relevant general assembly resolutions."},{"t":1249,"topic":"New Caledonia","text":"We remain concerned by the persistent social economic disparities affecting affecting the Canak people including inequalities in employment, education, income and access to economic opportunities. These long-standing structural imbalances continue to constrain the full and equitable enjoyment of economic, social, and cultural rights by indigenous cans. Notwithstanding the territories considerable natural resources and economic potential. Reports from the Evelyn case supported by independent assessment point to the enduring effects of economic marginalization and uneven development which may be understood as forms of structural violence in so far as they limit meaningful participation in an inequitable benefit from the territories development. Addressing these disparities is essential to fostering social cohesion and advancing a just inclusive and sustainable decolonization process. In this regard, Venato calls for the full implementation of relevant United Nation resolutions on the question of new Calonia and encourages continued engagement and constructive dialogue among all stakeholders including the administrating power and the representatives of the Kanak people."},{"t":1325,"topic":"Vanuatu-France dispute","text":"We further reaffirm the important role of the special committee on decolonization and the fourth committee in advancing the realization of self-determination and sh and ensuring that the rights aspirations and interests of the kanak people remain at the center of decolonization pro process. Mr. President at the end of August the FATU government initiated proceedings against France before the International Court of Justice concern concerning sovereignity over um N and um Lea Islands or Matthew and Hunter as they call in English and the maritime boundaries between Vanoatu and New Calonia. These islands are integral part of anatu's territory grounded in customary governance long-standing historical connections, indigenous ownership and is seen as part of our duty as ancestral custodians to protect and preserve. We recognize France as a steadfast champion of the international rules-based order and under the leadership of President Mron, a strong supporter of international judicial institutions."},{"t":1393,"topic":"France ICJ","text":"France has stood alongside Vonoatu in advancing global climate action, including through its support for initiative before the International Court of Justice. We greatly value this partnership and France leadership on issues of international importance. It is in the same spirit of mutual respect and commitment to international law that we respectfully invite France to consent to the jurisdiction of the court. Mr. President, trust is important for the United Nations credibility. It cannot be restored through declarations alone. Trust must be earned through action. People will trust the United Nations when they see it preventing conflict. They will trust it when international law is respected. They will trust it when humanitarian assistance reaches those who need it. They will trust it when development commitments become real projects. They will trust it when climate finance reach vulnerable communities. They will trust it when small states are ahead and they will trust it when the international system treats all nations with equal dign dignity."},{"t":1457,"topic":"UN reform","text":"For Vanoatu, restoring trust also means restoring confidence in the multilateral in multilateralism itself. We must resist the temptation to conclude that because the international system is imperfect, it is therefore irrelevant. The UN80 reforms currently implemented are paramount to rebuild trust again at the United Nations and therefore needs to be managed diligently. FATU supports efforts to strengthen the United Nations. But reform must preserve what is most important, the principle of sovereign equality. The United Nations cannot become an institution where the forces of the most powerful states dominate, where smaller states are expected merely to follow. Reform must strengthen general assembly. It must make international institutions more accessible to developing countries. It must address the financing and capacity constraints facing small delegations. It must strengthen prevented preventive diplomacy. It must improve implementation of international decisions decisions."},{"t":1518,"topic":"UN reform","text":"It must ensure that the development pillar remains resourced and that the implementation on the ground is effective and efficient. and it must ensure that international law remains central to the international system. Forato calls for UN Security Council that is more representative, transparent and accountable with and working methods that reflect today's realities and give all regions a meaningful voice. But reform cannot be limited to institutional structures. The deeper reform we require is political and renewed commitment by member states to the principles we have already agreed to that charter does not need to be reinvented. It needs to be respected. Mr. President, excellencies for veno the United Nations charter remain our compass. It tell it tells us that the nations are sovereign equals. It tells us that disputes must be settled peacefully. It tells us that the force must not be used against the treachery or political independence of states. It tells us that the nations must cooperate."},{"t":1581,"topic":"multilateralism","text":"It tells us and it reminds us that the ultimate purpose of the international system is not power for its own sake. It is peace, justice, human dignity, development and cooperation. And it is better future for succeeding generations. These principles are particularly important to Venuatu because we know what independence means. Our independence is not merely the absence of colonial rule. Independence means the right of our people to determine our future. It means sovereignity. It means dignity. It means equality. And it means having an equal place in the family of nations. That is why Venat will continue to defend the multilateral system. That is why we will continue to defend international law and that is why we will continue to speak for the principle that every nation regard regardless of size matters. Mr. President, we meet at a critical moment in international affairs. There are wars that remain unresolved."},{"t":1642,"topic":"multilateralism","text":"There are communities facing humanitarian catastrophe. There's growing geopolitical revoly. There is economic uncertainty. There is climate disruption. There is technological transformation. And there is declining confidence in the international systems institutions. Yet I remain convinced that this is precisely the moment when we must choose cooperation over confrontation. We must choose dialogue over division. We must choose law over force. We must choose solidarity over indifference. And we must choose multilateralism over fragmentation. Fatu comes from a part of the world where our ancestors navigated fast oceans using the stars, the winds, the currents and the knowledge pass from generation to generation. Today the international community is navigating another uncertain ocean. We need a campus. The United The United Nations Charter is that compass. It provides the principles by which we can navigate a world of competing interest while preserving our common humanity."},{"t":1705,"topic":"UN reform","text":"The theme of this ATV session, restoring trust, managing transformation, a United Nations that delivers for all reminds us of what is required. But ultimately, restoring trust will depend not on the watch we adopt here, but on the actions we take when we leave this hall. Let us therefore build a United Nations that is strong enough to prevent war, fair enough to protect the vulnerable, courageous enough to defend international law, and inclusive enough to give every nation a meaningful voice. Let us build a United Nations where the concerns of a small ally nation in the Pacific and all over the world can stand alongside those of the largest powers of the world. Let us not allow division to rule our era. Instead, we choose cooperation. We choose peace. We choose justice. We choose solidarity. And we choose to renew our faith in the idea that together nations can build a world. We can build a better world. Vatu stands ready to do its path."},{"t":1766,"topic":"Ceremony","text":"Thank you. I thank the chair of delegation of I would now give the floor to his excellency Mark"}],"compare":[{"topic":"UN & its reform","share":0.2386,"mean":0.2046,"rank":74,"others":170},{"topic":"International Law & Order","share":0.1548,"mean":0.0599,"rank":24,"others":102},{"topic":"Climate Change","share":0.118,"mean":0.0424,"rank":25,"others":77},{"topic":"Artificial Intelligence","share":0.0795,"mean":0.0503,"rank":49,"others":83},{"topic":"New Caledonia","share":0.0474,"mean":0.0,"rank":1,"others":0},{"topic":"Indonesia","share":0.0419,"mean":0.0004,"rank":2,"others":1},{"topic":"Vanuatu","share":0.0412,"mean":0.0,"rank":1,"others":0},{"topic":"France","share":0.0396,"mean":0.0004,"rank":2,"others":1}]};
